<?php
declare(strict_types=1);
namespace App\Controllers; use App\Core\Request;use App\Core\View;use App\Core\Response;use App\Core\Session;use App\Middleware\PermissionMiddleware;use App\Repositories\CategoryRepository;
final class CategoryController { public function index(Request $r):void{PermissionMiddleware::require('categories.view');$rows=(new CategoryRepository())->all();View::render('categories/index',compact('rows'));} public function store(Request $r):void{PermissionMiddleware::require('categories.create');verify_csrf();(new CategoryRepository())->create($r->all());Session::flash('success','Category created.');Response::redirect('/categories');} public function update(Request $r,string $id):void{PermissionMiddleware::require('categories.edit');verify_csrf();(new CategoryRepository())->update((int)$id,$r->all());Session::flash('success','Category updated.');Response::redirect('/categories');} public function delete(Request $r,string $id):void{PermissionMiddleware::require('categories.delete');verify_csrf();(new CategoryRepository())->delete((int)$id);Session::flash('success','Category deleted.');Response::redirect('/categories');}}
